1	/**
2	 * dodo-checkout — Edge Function
3	 *
4	 * Creates a Dodo Payments subscription checkout session for plan upgrades.
5	 *
6	 * Expected request body:
7	 *   { plan: 'pro' | 'agency'; billing_cycle: 'monthly' | 'annual' }
8	 *
9	 * Returns:
10	 *   { url: string } — Dodo-hosted checkout page URL
11	 *
12	 * Required env vars:
13	 *   DODO_API_KEY
14	 *   DODO_PRODUCT_PRO_MONTHLY
15	 *   DODO_PRODUCT_PRO_ANNUAL
16	 *   DODO_PRODUCT_AGENCY_MONTHLY
17	 *   DODO_PRODUCT_AGENCY_ANNUAL
18	 *   SITE_URL
19	 *   SUPABASE_URL
20	 *   SUPABASE_ANON_KEY
21	 *   SUPABASE_SERVICE_ROLE_KEY
22	 */
23	
24	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
25	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
26	
27	const corsHeaders = {
28	  "Access-Control-Allow-Origin": "*",
29	  "Access-Control-Allow-Headers":
30	    "authorization, x-client-info, apikey, content-type",
31	};
32	
33	function getProductId(plan: string, billingCycle: string): string | null {
34	  const map: Record<string, string> = {
35	    "pro:monthly": Deno.env.get("DODO_PRODUCT_PRO_MONTHLY") ?? "",
36	    "pro:annual": Deno.env.get("DODO_PRODUCT_PRO_ANNUAL") ?? "",
37	    "agency:monthly": Deno.env.get("DODO_PRODUCT_AGENCY_MONTHLY") ?? "",
38	    "agency:annual": Deno.env.get("DODO_PRODUCT_AGENCY_ANNUAL") ?? "",
39	  };
40	  return map[`${plan}:${billingCycle}`] || null;
41	}
42	
43	serve(async (req: Request) => {
44	  if (req.method === "OPTIONS") {
45	    return new Response("ok", { headers: corsHeaders });
46	  }
47	
48	  try {
49	    // ── 1. Auth ──────────────────────────────────────────────────────
50	    const authHeader = req.headers.get("Authorization");
51	    if (!authHeader) {
52	      return new Response(
53	        JSON.stringify({ error: "Missing Authorization header" }),
54	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
55	      );
56	    }
57	
58	    const supabaseUser = createClient(
59	      Deno.env.get("SUPABASE_URL") ?? "",
60	      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
61	      { global: { headers: { Authorization: authHeader } } }
62	    );
63	
64	    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
65	    if (userError || !user) {
66	      return new Response(
67	        JSON.stringify({ error: "Unauthorized" }),
68	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
69	      );
70	    }
71	
72	    // ── 2. Parse + validate body ─────────────────────────────────────
73	    let body: { plan?: string; billing_cycle?: string };
74	    try {
75	      body = await req.json();
76	    } catch {
77	      return new Response(
78	        JSON.stringify({ error: "Invalid JSON body" }),
79	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
80	      );
81	    }
82	
83	    const { plan, billing_cycle } = body;
84	
85	    if (!plan || !["pro", "agency"].includes(plan)) {
86	      return new Response(
87	        JSON.stringify({ error: "Invalid plan. Must be 'pro' or 'agency'." }),
88	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
89	      );
90	    }
91	
92	    if (!billing_cycle || !["monthly", "annual"].includes(billing_cycle)) {
93	      return new Response(
94	        JSON.stringify({ error: "Invalid billing_cycle. Must be 'monthly' or 'annual'." }),
95	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
96	      );
97	    }
98	
99	    const productId = getProductId(plan, billing_cycle);
100	    if (!productId) {
101	      console.error(`Missing product ID for ${plan}:${billing_cycle}`);
102	      return new Response(
103	        JSON.stringify({ error: "Pricing configuration error. Contact support." }),
104	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
105	      );
106	    }
107	
108	    // ── 3. Get user profile ──────────────────────────────────────────
109	    const supabaseAdmin = createClient(
110	      Deno.env.get("SUPABASE_URL") ?? "",
111	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
112	    );
113	
114	    const { data: profile, error: profileError } = await supabaseAdmin
115	      .from("profiles")
116	      .select("id, email, full_name, dodo_customer_id")
117	      .eq("id", user.id)
118	      .single();
119	
120	    if (profileError || !profile) {
121	      console.error("Profile fetch error:", profileError);
122	      return new Response(
123	        JSON.stringify({ error: "User profile not found." }),
124	        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
125	      );
126	    }
127	
128	    // ── 4. Build Dodo customer payload ───────────────────────────────
129	    const customerPayload = profile.dodo_customer_id
130	      ? { create_new_customer: false, customer_id: profile.dodo_customer_id }
131	      : {
132	          create_new_customer: true,
133	          email: profile.email ?? user.email,
134	          name: profile.full_name ?? "",
135	        };
136	
137	    const origin = Deno.env.get("SITE_URL") ?? "http://localhost:5173";
138	    const dodoApiKey = Deno.env.get("DODO_API_KEY") ?? "";
139	
140	    // ── 5. Create subscription checkout with payment link ────────────
141	    const dodoRes = await fetch("https://api.dodopayments.com/subscriptions", {
142	      method: "POST",
143	      headers: {
144	        "Authorization": `Bearer ${dodoApiKey}`,
145	        "Content-Type": "application/json",
146	      },
147	      body: JSON.stringify({
148	        billing: {
149	          currency: "USD",
150	          interval: billing_cycle === "annual" ? "year" : "month",
151	          interval_count: 1,
152	        },
153	        customer: customerPayload,
154	        product_id: productId,
155	        payment_link: true,
156	        return_url: `${origin}/dashboard?checkout=success`,
157	        metadata: {
158	          user_id: user.id,
159	          plan,
160	        },
161	      }),
162	    });
163	
164	    if (!dodoRes.ok) {
165	      const errText = await dodoRes.text();
166	      console.error("Dodo API error:", dodoRes.status, errText);
167	      return new Response(
168	        JSON.stringify({ error: "Failed to create checkout session." }),
169	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
170	      );
171	    }
172	
173	    const dodoData = await dodoRes.json();
174	
175	    // Persist customer ID if newly created
176	    if (!profile.dodo_customer_id && dodoData.customer_id) {
177	      const { error: updateError } = await supabaseAdmin
178	        .from("profiles")
179	        .update({ dodo_customer_id: dodoData.customer_id })
180	        .eq("id", user.id);
181	
182	      if (updateError) {
183	        // Non-fatal — will be captured via webhook
184	        console.error("Failed to persist dodo_customer_id:", updateError);
185	      }
186	    }
187	
188	    const checkoutUrl = dodoData.payment_link;
189	    if (!checkoutUrl) {
190	      console.error("No payment_link in Dodo response:", dodoData);
191	      return new Response(
192	        JSON.stringify({ error: "No checkout URL returned from payment provider." }),
193	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
194	      );
195	    }
196	
197	    return new Response(
198	      JSON.stringify({ url: checkoutUrl }),
199	      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
200	    );
201	  } catch (error: unknown) {
202	    const message = error instanceof Error ? error.message : "Internal server error";
203	    console.error("dodo-checkout error:", error);
204	    return new Response(
205	      JSON.stringify({ error: message }),
206	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
207	    );
208	  }
209	});
