1	/**
2	 * dodo-webhook — Edge Function
3	 *
4	 * Handles incoming Dodo Payments webhook events and keeps the profiles table
5	 * in sync with subscription state.
6	 *
7	 * Handled events:
8	 *   subscription.active          → activate plan, set scan_limit, billing_cycle_end
9	 *   subscription.renewed         → update billing_cycle_end
10	 *   subscription.cancelled       → downgrade to free, clear billing data
11	 *   subscription.on_hold         → log for observability
12	 *   payment.failed               → log for observability
13	 *   subscription.charge_failed   → log for observability
14	 *
15	 * Required env vars:
16	 *   DODO_WEBHOOK_SECRET          (from Dodo Payments dashboard → webhook endpoint)
17	 *   DODO_PRODUCT_PRO_MONTHLY
18	 *   DODO_PRODUCT_PRO_ANNUAL
19	 *   DODO_PRODUCT_AGENCY_MONTHLY
20	 *   DODO_PRODUCT_AGENCY_ANNUAL
21	 *   SUPABASE_URL
22	 *   SUPABASE_SERVICE_ROLE_KEY
23	 *
24	 * Security: Webhook signature is verified via standardwebhooks before any processing.
25	 */
26	
27	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
28	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
29	import { Webhook } from "https://esm.sh/standardwebhooks@1.0.0";
30	
31	// ── Plan config ───────────────────────────────────────────────────
32	
33	type PlanType = "free" | "pro" | "agency";
34	
35	const PLAN_LIMITS: Record<PlanType, number> = {
36	  free: 3,
37	  pro: 50,
38	  agency: 500,
39	};
40	
41	function getPlanFromProductId(productId: string): PlanType {
42	  const proMonthly = Deno.env.get("DODO_PRODUCT_PRO_MONTHLY");
43	  const proAnnual = Deno.env.get("DODO_PRODUCT_PRO_ANNUAL");
44	  const agencyMonthly = Deno.env.get("DODO_PRODUCT_AGENCY_MONTHLY");
45	  const agencyAnnual = Deno.env.get("DODO_PRODUCT_AGENCY_ANNUAL");
46	
47	  if (productId === proMonthly || productId === proAnnual) return "pro";
48	  if (productId === agencyMonthly || productId === agencyAnnual) return "agency";
49	
50	  console.warn(`Unknown product ID: ${productId}. Defaulting to 'pro'.`);
51	  return "pro";
52	}
53	
54	// ── Serve ─────────────────────────────────────────────────────────
55	
56	serve(async (req: Request) => {
57	  const body = await req.text();
58	
59	  const webhookSecret = Deno.env.get("DODO_WEBHOOK_SECRET");
60	  if (!webhookSecret) {
61	    console.error("DODO_WEBHOOK_SECRET env var not set");
62	    return new Response(
63	      JSON.stringify({ error: "Webhook secret not configured" }),
64	      { status: 500, headers: { "Content-Type": "application/json" } }
65	    );
66	  }
67	
68	  // ── Verify signature (standardwebhooks) ──────────────────────────
69	  let event: { type: string; data: Record<string, unknown> };
70	
71	  try {
72	    const wh = new Webhook(webhookSecret);
73	    const headers = {
74	      "webhook-id": req.headers.get("webhook-id") ?? "",
75	      "webhook-timestamp": req.headers.get("webhook-timestamp") ?? "",
76	      "webhook-signature": req.headers.get("webhook-signature") ?? "",
77	    };
78	    event = wh.verify(body, headers) as { type: string; data: Record<string, unknown> };
79	  } catch (err: unknown) {
80	    const message = err instanceof Error ? err.message : "Invalid signature";
81	    console.error("Webhook signature verification failed:", message);
82	    return new Response(
83	      JSON.stringify({ error: `Webhook verification failed: ${message}` }),
84	      { status: 400, headers: { "Content-Type": "application/json" } }
85	    );
86	  }
87	
88	  // ── Admin Supabase client (bypasses RLS) ─────────────────────────
89	  const supabase = createClient(
90	    Deno.env.get("SUPABASE_URL") ?? "",
91	    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
92	  );
93	
94	  // ── Event routing ─────────────────────────────────────────────────
95	  try {
96	    switch (event.type) {
97	      // ── subscription.active ──────────────────────────────────────
98	      // Fires when a new subscription is created and payment succeeds.
99	      case "subscription.active": {
100	        const sub = event.data as {
101	          subscription_id: string;
102	          customer_id: string;
103	          product_id: string;
104	          current_period_end?: number;
105	          metadata?: Record<string, string>;
106	        };
107	
108	        const userId = sub.metadata?.user_id;
109	        const plan = (sub.metadata?.plan ?? getPlanFromProductId(sub.product_id)) as PlanType;
110	
111	        if (!userId) {
112	          console.error("subscription.active: missing user_id in metadata");
113	          break;
114	        }
115	
116	        const billingCycleEnd = sub.current_period_end
117	          ? new Date(sub.current_period_end * 1000).toISOString()
118	          : null;
119	
120	        const { error } = await supabase
121	          .from("profiles")
122	          .update({
123	            plan,
124	            scan_limit: PLAN_LIMITS[plan] ?? PLAN_LIMITS.pro,
125	            dodo_subscription_id: sub.subscription_id,
126	            dodo_customer_id: sub.customer_id,
127	            billing_cycle_end: billingCycleEnd,
128	            updated_at: new Date().toISOString(),
129	          })
130	          .eq("id", userId);
131	
132	        if (error) {
133	          console.error("subscription.active profile update error:", error);
134	        } else {
135	          console.log(`Activated ${plan} plan for user ${userId}`);
136	        }
137	        break;
138	      }
139	
140	      // ── subscription.renewed ─────────────────────────────────────
141	      // Fires on each successful renewal cycle.
142	      case "subscription.renewed": {
143	        const sub = event.data as {
144	          subscription_id: string;
145	          customer_id: string;
146	          product_id: string;
147	          current_period_end?: number;
148	        };
149	
150	        const { data: profile, error: profileError } = await supabase
151	          .from("profiles")
152	          .select("id, plan")
153	          .eq("dodo_customer_id", sub.customer_id)
154	          .single();
155	
156	        if (profileError || !profile) {
157	          console.error(
158	            "subscription.renewed: profile not found for customer",
159	            sub.customer_id
160	          );
161	          break;
162	        }
163	
164	        const billingCycleEnd = sub.current_period_end
165	          ? new Date(sub.current_period_end * 1000).toISOString()
166	          : null;
167	
168	        const { error } = await supabase
169	          .from("profiles")
170	          .update({
171	            dodo_subscription_id: sub.subscription_id,
172	            billing_cycle_end: billingCycleEnd,
173	            updated_at: new Date().toISOString(),
174	          })
175	          .eq("id", profile.id);
176	
177	        if (error) {
178	          console.error("subscription.renewed profile update error:", error);
179	        } else {
180	          console.log(`Renewed subscription for user ${profile.id}`);
181	        }
182	        break;
183	      }
184	
185	      // ── subscription.cancelled ───────────────────────────────────
186	      // Fires when a subscription is cancelled (immediately or at period end).
187	      case "subscription.cancelled": {
188	        const sub = event.data as {
189	          subscription_id: string;
190	          customer_id: string;
191	        };
192	
193	        const { data: profile, error: profileError } = await supabase
194	          .from("profiles")
195	          .select("id")
196	          .eq("dodo_customer_id", sub.customer_id)
197	          .single();
198	
199	        if (profileError || !profile) {
200	          console.error(
201	            "subscription.cancelled: profile not found for customer",
202	            sub.customer_id
203	          );
204	          break;
205	        }
206	
207	        const { error } = await supabase
208	          .from("profiles")
209	          .update({
210	            plan: "free",
211	            scan_limit: PLAN_LIMITS.free,
212	            dodo_subscription_id: null,
213	            billing_cycle_end: null,
214	            updated_at: new Date().toISOString(),
215	          })
216	          .eq("id", profile.id);
217	
218	        if (error) {
219	          console.error("subscription.cancelled profile update error:", error);
220	        } else {
221	          console.log(`Downgraded user ${profile.id} to free plan (subscription cancelled)`);
222	        }
223	        break;
224	      }
225	
226	      // ── subscription.on_hold / payment.failed ────────────────────
227	      case "subscription.on_hold":
228	      case "payment.failed":
229	      case "subscription.charge_failed": {
230	        const data = event.data as {
231	          customer_id?: string;
232	          subscription_id?: string;
233	        };
234	        console.log(
235	          `${event.type} for customer ${data.customer_id ?? "unknown"}, subscription ${data.subscription_id ?? "unknown"}`
236	        );
237	        // Future: trigger a dunning email via send-email function
238	        break;
239	      }
240	
241	      default:
242	        console.log(`Unhandled webhook event type: ${event.type}`);
243	    }
244	
245	    return new Response(
246	      JSON.stringify({ received: true }),
247	      { status: 200, headers: { "Content-Type": "application/json" } }
248	    );
249	  } catch (error: unknown) {
250	    const message = error instanceof Error ? error.message : "Handler error";
251	    console.error(`Error handling ${event.type}:`, error);
252	    return new Response(
253	      JSON.stringify({ error: message }),
254	      { status: 500, headers: { "Content-Type": "application/json" } }
255	    );
256	  }
257	});
