1	/**
2	 * dodo-portal — Edge Function
3	 *
4	 * Creates a Dodo Payments Customer Portal session so users can manage
5	 * their subscription, payment method, and download invoices.
6	 *
7	 * Returns:
8	 *   { url: string } — Dodo-hosted portal URL
9	 *
10	 * Required env vars:
11	 *   DODO_API_KEY
12	 *   SUPABASE_URL
13	 *   SUPABASE_ANON_KEY
14	 *   SUPABASE_SERVICE_ROLE_KEY
15	 */
16	
17	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
18	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
19	
20	const corsHeaders = {
21	  "Access-Control-Allow-Origin": "*",
22	  "Access-Control-Allow-Headers":
23	    "authorization, x-client-info, apikey, content-type",
24	};
25	
26	serve(async (req: Request) => {
27	  if (req.method === "OPTIONS") {
28	    return new Response("ok", { headers: corsHeaders });
29	  }
30	
31	  try {
32	    // ── 1. Auth ────────────────────────────────────────────────────
33	    const authHeader = req.headers.get("Authorization");
34	    if (!authHeader) {
35	      return new Response(
36	        JSON.stringify({ error: "Missing Authorization header" }),
37	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
38	      );
39	    }
40	
41	    const supabaseUser = createClient(
42	      Deno.env.get("SUPABASE_URL") ?? "",
43	      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
44	      { global: { headers: { Authorization: authHeader } } }
45	    );
46	
47	    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
48	    if (userError || !user) {
49	      return new Response(
50	        JSON.stringify({ error: "Unauthorized" }),
51	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
52	      );
53	    }
54	
55	    // ── 2. Get profile and dodo_customer_id ────────────────────────
56	    const supabaseAdmin = createClient(
57	      Deno.env.get("SUPABASE_URL") ?? "",
58	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
59	    );
60	
61	    const { data: profile, error: profileError } = await supabaseAdmin
62	      .from("profiles")
63	      .select("dodo_customer_id")
64	      .eq("id", user.id)
65	      .single();
66	
67	    if (profileError || !profile?.dodo_customer_id) {
68	      return new Response(
69	        JSON.stringify({
70	          error: "No active subscription found. Please upgrade to a paid plan first.",
71	        }),
72	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
73	      );
74	    }
75	
76	    // ── 3. Fetch Dodo Customer Portal URL ──────────────────────────
77	    const dodoApiKey = Deno.env.get("DODO_API_KEY") ?? "";
78	
79	    const portalRes = await fetch(
80	      `https://api.dodopayments.com/customers/${profile.dodo_customer_id}/portal`,
81	      {
82	        method: "GET",
83	        headers: {
84	          "Authorization": `Bearer ${dodoApiKey}`,
85	        },
86	      }
87	    );
88	
89	    if (!portalRes.ok) {
90	      const errText = await portalRes.text();
91	      console.error("Dodo portal API error:", portalRes.status, errText);
92	      return new Response(
93	        JSON.stringify({ error: "Failed to create billing portal session." }),
94	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
95	      );
96	    }
97	
98	    const portalData = await portalRes.json();
99	    const portalUrl = portalData.link ?? portalData.url;
100	
101	    if (!portalUrl) {
102	      console.error("No portal URL in Dodo response:", portalData);
103	      return new Response(
104	        JSON.stringify({ error: "No portal URL returned from payment provider." }),
105	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
106	      );
107	    }
108	
109	    return new Response(
110	      JSON.stringify({ url: portalUrl }),
111	      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
112	    );
113	  } catch (error: unknown) {
114	    const message = error instanceof Error ? error.message : "Internal server error";
115	    console.error("dodo-portal error:", error);
116	    return new Response(
117	      JSON.stringify({ error: message }),
118	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
119	    );
120	  }
121	});
122
